//! Native proof loading; circuit inputs and verifiers are generated by Zolana macros.
use anyhow::Result;
use dvp_program::circuits;
use std::path::PathBuf;
use zolana_program::{CompressedProof, Groth16Keys, Groth16Prover, SolanaVerifyingKey, ZkCircuit};

#[derive(Debug, thiserror::Error)]
pub enum ProveError {
    #[error(transparent)]
    Prover(#[from] zolana_program::ProverError),
    #[error("{0}")]
    Keys(String),
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum CircuitId {
    CreateDvp,
    ReclaimDvp,
    SettleDvp,
    AbortDvp,
}
impl CircuitId {
    pub const ALL: [Self; 4] = [
        Self::CreateDvp,
        Self::ReclaimDvp,
        Self::SettleDvp,
        Self::AbortDvp,
    ];
    pub fn name(self) -> &'static str {
        match self {
            Self::CreateDvp => "create_dvp",
            Self::ReclaimDvp => "reclaim_dvp",
            Self::SettleDvp => "settle_dvp",
            Self::AbortDvp => "abort_dvp",
        }
    }
}
pub fn keys_dir() -> PathBuf {
    std::env::var_os("DVP_KEYS_DIR")
        .map(PathBuf::from)
        .unwrap_or_else(|| {
            PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../target/zk/dvp-program")
        })
}

/// The manifest is trusted source metadata, never fetched alongside an untrusted key.
pub fn key_checksum(circuit: CircuitId) -> Result<[u8; 32], ProveError> {
    let filename = format!("{}.pk", circuit.name());
    let digest = include_str!("../../dvp-keys.CHECKSUM")
        .lines()
        .find_map(|line| {
            let mut parts = line.split_whitespace();
            let hash = parts.next()?;
            (parts.next()? == filename).then_some(hash)
        })
        .ok_or_else(|| {
            ProveError::Keys(format!("no checksum for {filename}; regenerate DvP keys"))
        })?;
    if digest.len() != 64 {
        return Err(ProveError::Keys("invalid DvP key checksum".into()));
    }
    let mut bytes = [0; 32];
    for (byte, offset) in bytes.iter_mut().zip((0..64).step_by(2)) {
        *byte = u8::from_str_radix(
            digest
                .get(offset..offset + 2)
                .ok_or_else(|| ProveError::Keys("invalid key checksum".into()))?,
            16,
        )
        .map_err(|error| ProveError::Keys(error.to_string()))?;
    }
    Ok(bytes)
}

pub fn keys(id: CircuitId) -> Result<Groth16Keys, ProveError> {
    Ok(Groth16Keys::load_image_checked(
        &keys_dir().join(format!("{}.pk", id.name())),
        &key_checksum(id)?,
    )?)
}

pub fn prove<P: ZkCircuit + 'static>(id: CircuitId, inputs: &P) -> Result<CompressedProof> {
    let prover = Groth16Prover::<P>::new(keys(id)?)?;
    Ok(CompressedProof::try_from(&prover.prove(inputs)?.proof)?)
}

pub fn verifying_key(id: CircuitId) -> Result<SolanaVerifyingKey, ProveError> {
    Ok(keys(id)?.verifying_key().clone())
}

pub fn constraint_count(id: CircuitId) -> Result<usize> {
    fn count<P: ZkCircuit + 'static>(id: CircuitId) -> Result<usize> {
        Ok(Groth16Prover::<P>::new(keys(id)?)?.constraint_count())
    }
    match id {
        CircuitId::CreateDvp => count::<circuits::CreateDvp>(id),
        CircuitId::ReclaimDvp => count::<circuits::ReclaimDvp>(id),
        CircuitId::SettleDvp => count::<circuits::SettleDvp>(id),
        CircuitId::AbortDvp => count::<circuits::AbortDvp>(id),
    }
}
